    # color the missing terminal cells with 1.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    colored_rows = [r for r in range(h) if any(v != bg for v in g[r])]
    # Pair similar horizontal rows by their number of non-background cells.
    for i, r1 in enumerate(colored_rows):
        for r2 in colored_rows[i + 1:]:
            a, b = g[r1], g[r2]
            na = sum(v != bg for v in a)
            nb = sum(v != bg for v in b)
            if na == nb:
                continue
