    for row in src:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # A motif is a run of rows containing non-background cells; blank rows
    # separate repeated copies.
    bands = []
    r = 0
    while r < h:
        if all(value == bg for value in src[r]):
            r += 1
            continue
        start = r
        while r < h and any(value != bg for value in src[r]):
            r += 1
        bands.append((start, r))

    # Compare corresponding rows of equally tall motifs. Only a differing
    # suffix that reaches the right edge is significant; mark its background
    # side with color 1.
    for i, (a0, a1) in enumerate(bands):
